    24	    public String generateOccupancyReport(LocalDate date) {
    25	        List<Reservation> occupiedReservations = reservationRepository.findPaidByDate(date);
    26	        List<Room> allRooms = roomRepository.findAll();
    27	
    28	        StringBuilder csv = new StringBuilder();
    29	        csv.append("room,type,reservation,check_in,check_out\n");
    30	
    31	        for (Reservation res : occupiedReservations) {
    32	            Room room = roomRepository.findByNumber(res.roomNumber())
    33	                .orElseThrow(() -> new RuntimeException("Room not found"));
    34	
    35	            csv.append(res.roomNumber()).append(",");
    36	            csv.append(room.type().name()).append(",");
    37	            csv.append(res.id()).append(",");
    38	            csv.append(res.checkIn().format(DATE_FORMATTER)).append(",");
    39	            csv.append(res.checkOut().format(DATE_FORMATTER)).append("\n");
    40	        }
    41	
    42	        csv.append("total,").append(occupiedReservations.size()).append("/").append(allRooms.size());
    43	
    44	        return csv.toString();
    45	    }
    46	
    47	    public String generateRevenueReport(YearMonth month) {
    48	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
    49	
    50	        StringBuilder csv = new StringBuilder();
    51	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    52	
    53	        BigDecimal total = BigDecimal.ZERO;
    54	
    55	        for (Reservation res : reservations) {
    56	            BigDecimal revenue = calculateRevenue(res);
    57	
    58	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
    59	                csv.append(res.id()).append(",");
    60	                csv.append(res.roomNumber()).append(",");
    61	                csv.append(res.checkIn().format(DATE_FORMATTER)).append(",");
    62	                csv.append(res.checkOut().format(DATE_FORMATTER)).append(",");
    63	                csv.append(res.status().name()).append(",");
    64	                csv.append(formatDecimal(revenue)).append("\n");
    65	
    66	                total = total.add(revenue);
    67	            }
    68	        }
    69	
    70	        csv.append("total,").append(formatDecimal(total));
    71	
    72	        return csv.toString();
    73	    }
    74	
    75	    private BigDecimal calculateRevenue(Reservation reservation) {
    76	        BigDecimal paid = reservation.amountPaid() != null ? reservation.amountPaid() : BigDecimal.ZERO;
    77	        BigDecimal refunded = reservation.refund() != null ? reservation.refund() : BigDecimal.ZERO;
    78	        return paid.subtract(refunded);
    79	    }
    80	
    81	    private String formatDecimal(BigDecimal value) {
    82	        return value.toPlainString();
    83	    }
    84	}
