     7	public final class EmailValidationRule implements MessageRule {
     8	    @Override
     9	    public ProcessingResult process(OutgoingMessage message) {
    10	        if (!isValidEmail(message.to())) {
    11	            return ProcessingResult.block(message);
    12	        }
    13	        return ProcessingResult.proceed(message);
    14	    }
    15	
    16	    private boolean isValidEmail(String email) {
    17	        if (email == null || email.isEmpty()) {
    18	            return false;
    19	        }
    20	
    21	        long atCount = email.chars().filter(ch -> ch == '@').count();
    22	        if (atCount != 1) {
    23	            return false;
    24	        }
    25	
    26	        int atIndex = email.indexOf('@');
    27	        if (atIndex == 0 || atIndex == email.length() - 1) {
    28	            return false;
    29	        }
    30	
    31	        String domain = email.substring(atIndex + 1);
    32	        if (!domain.contains(".")) {
    33	            return false;
    34	        }
    35	
    36	        int dotIndex = domain.indexOf('.');
    37	        if (dotIndex == 0 || dotIndex == domain.length() - 1) {
    38	            return false;
    39	        }
    40	
    41	        return true;
    42	    }
    43	}
