     1	package com.pousadamarealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public final class PriceCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    11	
    12	    public BigDecimal calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
    13	        BigDecimal subtotal = BigDecimal.ZERO;
    14	        LocalDate date = checkIn;
    15	
    16	        while (date.isBefore(checkOut)) {
    17	            BigDecimal nightRate = roomType.nightlyRate();
    18	            if (isHighSeason(date)) {
    19	                nightRate = nightRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
    20	            }
    21	            subtotal = subtotal.add(nightRate);
    22	            date = date.plusDays(1);
    23	        }
    24	
    25	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    26	    }
    27	
    28	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    29	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    30	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT).setScale(2, RoundingMode.HALF_EVEN);
    31	        }
    32	        return BigDecimal.ZERO;
    33	    }
    34	
    35	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    36	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    37	    }
    38	
    39	    private boolean isHighSeason(LocalDate date) {
    40	        Month month = date.getMonth();
    41	        int day = date.getDayOfMonth();
    42	
    43	        if (month == Month.JULY) {
    44	            return true;
    45	        }
    46	
    47	        if (month == Month.DECEMBER && day >= 15) {
    48	            return true;
    49	        }
    50	
    51	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    52	            return true;
    53	        }
    54	
    55	        return false;
    56	    }
    57	}
