    32	
    33	    private Reservation insert(Reservation reservation) {
    34	        String sql = """
    35	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
    36	                                     guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
    37	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    38	            RETURNING id
    39	        """;
    40	
    41	        try (var conn = dataSource.getConnection();
    42	             var stmt = conn.prepareStatement(sql)) {
    43	
    44	            stmt.setString(1, reservation.roomNumber());
    45	            stmt.setString(2, reservation.guestName());
    46	            stmt.setString(3, reservation.guestEmail());
    47	            stmt.setString(4, reservation.guestCpf());
    48	            stmt.setDate(5, Date.valueOf(reservation.checkIn()));
    49	            stmt.setDate(6, Date.valueOf(reservation.checkOut()));
    50	            stmt.setInt(7, reservation.guests());
    51	            stmt.setString(8, reservation.ratePlan().name());
