    32	    private void initializeSchema() {
    33	        try (Connection conn = dataSource.getConnection();
    34	             Statement stmt = conn.createStatement()) {
    35	
    36	            stmt.execute("""
    37	                CREATE TABLE IF NOT EXISTS rooms (
    38	                    number VARCHAR(10) PRIMARY KEY,
    39	                    type VARCHAR(20) NOT NULL
    40	                )
    41	            """);
    42	
    43	            stmt.execute("""
