    11	public final class Database {
    12	    private final HikariDataSource dataSource;
    13	
    14	    public Database(String jdbcUrl, String username, String password) {
    15	        HikariConfig config = new HikariConfig();
    16	        config.setJdbcUrl(jdbcUrl);
    17	        config.setUsername(username);
    18	        config.setPassword(password);
    19	        config.setMaximumPoolSize(10);
    20	        this.dataSource = new HikariDataSource(config);
    21	        initializeSchema();
    22	    }
    23	
    24	    public DataSource getDataSource() {
    25	        return dataSource;
    26	    }
    27	
    28	    public void close() {
    29	        dataSource.close();
    30	    }
    31	
    32	    private void initializeSchema() {
    33	        try (Connection conn = dataSource.getConnection();
    34	             Statement stmt = conn.createStatement()) {
    35	
    36	            stmt.execute("""
    37	                CREATE TABLE IF NOT EXISTS rooms (
    38	                    number VARCHAR(10) PRIMARY KEY,
    39	                    type VARCHAR(20) NOT NULL
    40	                )
    41	            """);
    42	
    43	            stmt.execute("""
    44	                CREATE TABLE IF NOT EXISTS reservations (
    45	                    id BIGSERIAL PRIMARY KEY,
    46	                    room_number VARCHAR(10) NOT NULL,
    47	                    guest_name VARCHAR(255) NOT NULL,
    48	                    guest_email VARCHAR(255) NOT NULL,
    49	                    guest_cpf VARCHAR(14) NOT NULL,
    50	                    check_in DATE NOT NULL,
    51	                    check_out DATE NOT NULL,
    52	                    guests INT NOT NULL,
    53	                    rate_plan VARCHAR(20) NOT NULL,
    54	                    nights INT NOT NULL,
    55	                    subtotal DECIMAL(10, 2) NOT NULL,
    56	                    discount DECIMAL(10, 2) NOT NULL,
    57	                    total DECIMAL(10, 2) NOT NULL,
    58	                    status VARCHAR(20) NOT NULL,
    59	                    amount_paid DECIMAL(10, 2) NOT NULL,
    60	                    refund DECIMAL(10, 2),
    61	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
    62	                )
    63	            """);
    64	
    65	            stmt.execute("""
    66	                CREATE TABLE IF NOT EXISTS messages (
    67	                    id BIGSERIAL PRIMARY KEY,
    68	                    channel VARCHAR(20) NOT NULL,
    69	                    recipient VARCHAR(255) NOT NULL,
    70	                    subject VARCHAR(500) NOT NULL,
    71	                    body TEXT NOT NULL,
    72	                    status VARCHAR(20) NOT NULL
    73	                )
    74	            """);
    75	
    76	            insertRoomsIfEmpty(conn);
    77	
    78	        } catch (SQLException e) {
    79	            throw new RuntimeException("Failed to initialize database schema", e);
    80	        }
    81	    }
    82	
    83	    private void insertRoomsIfEmpty(Connection conn) throws SQLException {
    84	        try (var stmt = conn.createStatement();
