122	public final class ApiController {
123	    private final ReservationService reservationService;
124	    private final RoomRepository roomRepository;
125	    private final MessageService messageService;
126	    private final ReportService reportService;
127	
128	    public ApiController(ReservationService reservationService, RoomRepository roomRepository,
129	                        MessageService messageService, ReportService reportService) {
