143	    public void createReservation(Context ctx) {
144	        try {
145	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
146	
147	            LocalDate checkIn = parseDate(request.checkIn());
148	            LocalDate checkOut = parseDate(request.checkOut());
149	
150	            if (!checkOut.isAfter(checkIn)) {
151	                throw new ValidationException("Check-out must be after check-in");
152	            }
153	
154	            RatePlan ratePlan = parseRatePlan(request.ratePlan());
155	
156	            Reservation reservation = reservationService.createReservation(
157	                request.roomNumber(),
158	                request.guestName(),
159	                request.guestEmail(),
160	                request.guestCpf(),
161	                checkIn,
162	                checkOut,
163	                request.guests(),
164	                ratePlan
165	            );
166	
167	            ctx.status(HttpStatus.CREATED);
168	            ctx.json(ReservationDto.from(reservation));
169	
170	        } catch (ValidationException e) {
171	            ctx.status(HttpStatus.BAD_REQUEST);
172	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
173	        } catch (ReservationService.RoomNotFoundException e) {
174	            ctx.status(HttpStatus.NOT_FOUND);
175	            ctx.json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
176	        } catch (ReservationService.RoomUnavailableException e) {
177	            ctx.status(HttpStatus.CONFLICT);
178	            ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
179	        } catch (ReservationService.CapacityExceededException e) {
180	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT);
181	            ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
182	        } catch (ReservationService.InvalidRequestException e) {
