240	
241	    public void checkOut(Context ctx) {
242	        try {
243	            Long id = Long.parseLong(ctx.pathParam("id"));
244	            Reservation reservation = reservationService.checkOut(id);
245	            Room room = roomRepository.findByNumber(reservation.roomNumber())
246	                .orElseThrow(() -> new RuntimeException("Room not found"));
247	            ctx.json(DocumentDto.from(reservation, room));
248	        } catch (ReservationService.ReservationNotFoundException e) {
249	            ctx.status(HttpStatus.NOT_FOUND);
250	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
