254	        }
255	    }
256	
257	    public void getDocument(Context ctx) {
258	        try {
259	            Long id = Long.parseLong(ctx.pathParam("id"));
260	            Reservation reservation = reservationService.getReservation(id);
261	
262	            if (reservation.amountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
263	                ctx.status(HttpStatus.BAD_REQUEST);
264	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Document only available for paid reservations"));
265	                return;
266	            }
267	
268	            Room room = roomRepository.findByNumber(reservation.roomNumber())
269	                .orElseThrow(() -> new RuntimeException("Room not found"));
270	            ctx.json(DocumentDto.from(reservation, room));
271	        } catch (ReservationService.ReservationNotFoundException e) {
272	            ctx.status(HttpStatus.NOT_FOUND);
273	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
274	        }
275	    }
