284	    public void getOccupancyReport(Context ctx) {
285	        try {
286	            String dateStr = ctx.queryParam("date");
287	            if (dateStr == null || dateStr.isEmpty()) {
288	                ctx.status(HttpStatus.BAD_REQUEST);
289	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
290	                return;
291	            }
292	
293	            LocalDate date = parseDate(dateStr);
294	            String csv = reportService.generateOccupancyReport(date);
295	
296	            ctx.contentType("text/csv; charset=utf-8");
297	            ctx.result(csv);
298	        } catch (ValidationException e) {
299	            ctx.status(HttpStatus.BAD_REQUEST);
300	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
301	        }
302	    }
303	
304	    public void getRevenueReport(Context ctx) {
305	        try {
306	            String monthStr = ctx.queryParam("month");
307	            if (monthStr == null || monthStr.isEmpty()) {
308	                ctx.status(HttpStatus.BAD_REQUEST);
309	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
310	                return;
311	            }
312	
313	            YearMonth month = parseMonth(monthStr);
314	            String csv = reportService.generateRevenueReport(month);
315	
316	            ctx.contentType("text/csv; charset=utf-8");
317	            ctx.result(csv);
318	        } catch (ValidationException e) {
319	            ctx.status(HttpStatus.BAD_REQUEST);
320	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
321	        }
322	    }
323	
324	    private LocalDate parseDate(String dateStr) {
325	        try {
326	            return LocalDate.parse(dateStr);
327	        } catch (DateTimeParseException e) {
328	            throw new ValidationException("Invalid date format");
329	        }
330	    }
331	
332	    private YearMonth parseMonth(String monthStr) {
333	        try {
334	            return YearMonth.parse(monthStr);
335	        } catch (DateTimeParseException e) {
336	            throw new ValidationException("Invalid month format");
337	        }
338	    }
339	
340	    private RatePlan parseRatePlan(String ratePlanStr) {
341	        try {
342	            return RatePlan.valueOf(ratePlanStr);
343	        } catch (IllegalArgumentException e) {
344	            throw new ValidationException("Invalid rate plan");
345	        }
346	    }
347	
348	    private static class ValidationException extends RuntimeException {
349	        ValidationException(String message) {
350	            super(message);
351	        }
352	    }
353	}

