  6	import java.math.BigDecimal;
  7	import java.time.LocalDate;
  8	import java.time.format.DateTimeFormatter;
  9	import java.util.Locale;
 10	
 11	public final class DocumentFormatter {
 12	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 13	    private static final Locale BRAZILIAN_LOCALE = new Locale("pt", "BR");
 14	
 15	    public static String formatReceipt(Reservation reservation, Room room) {
 16	        StringBuilder sb = new StringBuilder();
 17	
 18	        sb.append("Comprovante de reserva nº ").append(reservation.id()).append("\n");
 19	        sb.append("Hóspede: ").append(reservation.guestName())
 20	            .append(" (CPF ").append(formatCpf(reservation.guestCpf())).append(")\n");
 21	        sb.append("Quarto: ").append(room.number()).append(" (").append(room.type().name()).append(")\n");
 22	        sb.append("Entrada: ").append(formatDate(reservation.checkIn()))
 23	            .append(" | Saída: ").append(formatDate(reservation.checkOut()))
 24	            .append(" | ").append(formatNights(reservation.nights())).append("\n");
 25	        sb.append("Diárias: ").append(formatMoney(reservation.subtotal())).append("\n");
 26	
 27	        if (reservation.discount().compareTo(BigDecimal.ZERO) > 0) {
 28	            sb.append("Desconto: ").append(formatMoney(reservation.discount())).append("\n");
 29	        }
 30	
 31	        sb.append("Total: ").append(formatMoney(reservation.total()));
 32	
 33	        return sb.toString();
 34	    }
 35	
 36	    private static String formatDate(LocalDate date) {
 37	        return date.format(DATE_FORMATTER);
 38	    }
 39	
 40	    private static String formatMoney(BigDecimal amount) {
 41	        return String.format(BRAZILIAN_LOCALE, "R$ %,.2f", amount);
 42	    }
 43	
 44	    private static String formatNights(int nights) {
 45	        return nights == 1 ? "1 diária" : nights + " diárias";
 46	    }
 47	
 48	    private static String formatCpf(String cpf) {
 49	        if (cpf.length() == 11) {
 50	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
 51	        }
 52	        return cpf;
 53	    }
 54	}
