 61	
 62	import java.math.BigDecimal;
 63	import java.time.LocalDate;
 64	import java.time.YearMonth;
 65	import java.time.format.DateTimeFormatter;
 66	import java.util.List;
 67	
 68	public final class ReportService {
 69	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 70	    private final ReservationRepository reservationRepository;
 71	    private final RoomRepository roomRepository;
 72	
 73	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
 74	        this.reservationRepository = reservationRepository;
 75	        this.roomRepository = roomRepository;
 76	    }
 77	
 78	    public String generateOccupancyReport(LocalDate date) {
 79	        List<Reservation> occupiedReservations = reservationRepository.findPaidByDate(date);
 80	        List<Room> allRooms = roomRepository.findAll();
 81	
 82	        StringBuilder csv = new StringBuilder();
 83	        csv.append("room,type,reservation,check_in,check_out\n");
 84	
 85	        for (Reservation res : occupiedReservations) {
 86	            Room room = roomRepository.findByNumber(res.roomNumber())
 87	                .orElseThrow(() -> new RuntimeException("Room not found"));
 88	
 89	            csv.append(res.roomNumber()).append(",");
 90	            csv.append(room.type().name()).append(",");
 91	            csv.append(res.id()).append(",");
 92	            csv.append(res.checkIn().format(DATE_FORMATTER)).append(",");
 93	            csv.append(res.checkOut().format(DATE_FORMATTER)).append("\n");
 94	        }
 95	
 96	        csv.append("total,").append(occupiedReservations.size()).append("/").append(allRooms.size());
 97	
 98	        return csv.toString();
 99	    }
100	
101	    public String generateRevenueReport(YearMonth month) {
102	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
103	
104	        StringBuilder csv = new StringBuilder();
105	        csv.append("reservation,room,check_in,check_out,status,amount\n");
106	
107	        BigDecimal total = BigDecimal.ZERO;
108	
109	        for (Reservation res : reservations) {
110	            BigDecimal revenue = calculateRevenue(res);
111	
112	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
113	                csv.append(res.id()).append(",");
114	                csv.append(res.roomNumber()).append(",");
115	                csv.append(res.checkIn().format(DATE_FORMATTER)).append(",");
116	                csv.append(res.checkOut().format(DATE_FORMATTER)).append(",");
117	                csv.append(res.status().name()).append(",");
118	                csv.append(formatDecimal(revenue)).append("\n");
119	
120	                total = total.add(revenue);
121	            }
122	        }
123	
124	        csv.append("total,").append(formatDecimal(total));
125	
126	        return csv.toString();
127	    }
128	
129	    private BigDecimal calculateRevenue(Reservation reservation) {
130	        BigDecimal paid = reservation.amountPaid() != null ? reservation.amountPaid() : BigDecimal.ZERO;
131	        BigDecimal refunded = reservation.refund() != null ? reservation.refund() : BigDecimal.ZERO;
132	        return paid.subtract(refunded);
133	    }
134	
135	    private String formatDecimal(BigDecimal value) {
136	        return value.toPlainString();
137	    }
138	}
