151	public final class ReservationService {
152	    private final ReservationRepository reservationRepository;
153	    private final RoomRepository roomRepository;
154	    private final MessageService messageService;
155	    private final PriceCalculator priceCalculator;
156	
157	    public ReservationService(ReservationRepository reservationRepository, RoomRepository roomRepository,
158	                             MessageService messageService, PriceCalculator priceCalculator) {
159	        this.reservationRepository = reservationRepository;
160	        this.roomRepository = roomRepository;
161	        this.messageService = messageService;
162	        this.priceCalculator = priceCalculator;
163	    }
164	
165	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
166	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
167	        Room room = roomRepository.findByNumber(roomNumber)
168	            .orElseThrow(() -> new RoomNotFoundException(roomNumber));
169	
170	        if (guests > room.capacity()) {
171	            throw new CapacityExceededException();
172	        }
173	
174	        if (guests < 1) {
175	            throw new InvalidRequestException("At least one guest is required");
176	        }
177	
178	        List<Reservation> conflicts = reservationRepository.findActiveByRoomAndDateRange(roomNumber, checkIn, checkOut);
179	        if (!conflicts.isEmpty()) {
180	            throw new RoomUnavailableException();
181	        }
182	
183	        Reservation reservation = Reservation.create(roomNumber, room.type(), guestName, guestEmail, guestCpf,
184	            checkIn, checkOut, guests, ratePlan, priceCalculator);
185	
186	        return reservationRepository.save(reservation);
187	    }
188	
189	    public Reservation getReservation(Long id) {
190	        return reservationRepository.findById(id)
191	            .orElseThrow(() -> new ReservationNotFoundException(id));
192	    }
193	
194	    public Reservation confirmReservation(Long id) {
195	        Reservation reservation = getReservation(id);
196	
197	        try {
198	            reservation.confirm();
199	        } catch (IllegalStateException e) {
200	            throw new OperationNotAllowedException();
201	        }
202	
203	        Reservation updated = reservationRepository.save(reservation);
204	        sendConfirmationEmail(updated);
205	        return updated;
206	    }
207	
208	    public Reservation cancelReservation(Long id) {
209	        Reservation reservation = getReservation(id);
210	
211	        try {
212	            reservation.cancel();
213	        } catch (IllegalStateException e) {
214	            throw new OperationNotAllowedException();
215	        }
216	
217	        return reservationRepository.save(reservation);
218	    }
219	
220	    public Reservation checkIn(Long id) {
221	        Reservation reservation = getReservation(id);
222	
223	        try {
224	            reservation.performCheckIn();
225	        } catch (IllegalStateException e) {
226	            throw new OperationNotAllowedException();
227	        }
228	
229	        return reservationRepository.save(reservation);
230	    }
231	
232	    public Reservation checkOut(Long id) {
233	        Reservation reservation = getReservation(id);
234	
235	        try {
236	            reservation.performCheckOut();
237	        } catch (IllegalStateException e) {
238	            throw new OperationNotAllowedException();
239	        }
240	
241	        return reservationRepository.save(reservation);
242	    }
243	
244	    private void sendConfirmationEmail(Reservation reservation) {
245	        Room room = roomRepository.findByNumber(reservation.roomNumber())
246	            .orElseThrow(() -> new RuntimeException("Room not found"));
247	        String receipt = DocumentFormatter.formatReceipt(reservation, room);
248	        String subject = "Reserva confirmada - Pousada Maré Alta";
249	        String body = String.format("""
250	            Olá, %s!
251	
252	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
253	
254	            %s
255	
256	            A entrada é a partir das 14h, e a saída, até as 12h.
257	            Até breve!
258	            """, reservation.guestName(), receipt);
259	
260	        OutgoingMessage message = new OutgoingMessage(
261	            MessageChannel.EMAIL,
262	            reservation.guestEmail(),
263	            subject,
264	            body
265	        );
266	
267	        messageService.send(message);
268	    }
269	
270	    public static class RoomNotFoundException extends RuntimeException {
271	        public RoomNotFoundException(String roomNumber) {
272	            super("Room not found: " + roomNumber);
273	        }
274	    }
275	
276	    public static class ReservationNotFoundException extends RuntimeException {
277	        public ReservationNotFoundException(Long id) {
278	            super("Reservation not found: " + id);
279	        }
280	    }
281	
282	    public static class RoomUnavailableException extends RuntimeException {}
283	    public static class CapacityExceededException extends RuntimeException {}
284	    public static class OperationNotAllowedException extends RuntimeException {}
285	    public static class InvalidRequestException extends RuntimeException {
286	        public InvalidRequestException(String message) {
287	            super(message);
288	        }
289	    }
290	}

